    /// A stand-in model: each output pixel is its cell's first plane, times `k`.
    fn model(k: f32) -> RunTile {
        Arc::new(move |input: &[f32]| {
            let t = T;
            let mut out = vec![0f32; 3 * 4 * t * t];
            for c in 0..3 {
                for y in 0..2 * t {
                    for x in 0..2 * t {
                        out[(c * 2 * t + y) * 2 * t + x] = input[(y / 2) * t + x / 2] * k;
                    }
