        assert!(talk(&[hdr.as_bytes(), &bomb].concat()).contains("false"));
        assert!(Remote::new(&addr, TOKEN, "aa11", T).hello().is_ok());
        assert!(same("abc", "abc") && !same("abc", "abd") && !same("abc", "abcd"));
