        let l = TcpListener::bind("127.0.0.1:0").unwrap();
        let opts = ServerOptions { token: "short".into(), ..Default::default() };
        assert!(serve(l, id("aa11"), T, "x".into(), model(1.0), opts, Arc::new(|_| {})).is_err());
